import{_ as e,c as a,o as i,ae as l}from"./chunks/framework.Bi6zybwU.js";const h=JSON.parse('{"title":"Table Title/Description Settings","description":"Table Title/Description Settings","frontmatter":{"title":"Table Title/Description Settings","description":"Table Title/Description Settings"},"headers":[],"relativePath":"guide/table-management/table-title-description-settings.md","filePath":"guide/table-management/table-title-description-settings.md"}'),n={name:"guide/table-management/table-title-description-settings.md"};function o(s,t,r,d,b,c){return i(),a("div",null,[...t[0]||(t[0]=[l('<h1 id="table-title-description-settings" tabindex="-1">Table Title/Description Settings <a class="header-anchor" href="#table-title-description-settings" aria-label="Permalink to &quot;Table Title/Description Settings&quot;">​</a></h1><p>To add a new table, you need to add the** Table Title** and <strong>Table Description</strong> first. Let&#39;s dive into this simple guide to learn about Table Titles and Descriptions. In Ninja Tables, the table title is mandatory but the description is optional.</p><ul><li>First, go to the** Ninja Tables dashboard →** click on the **Add Table <strong>button</strong> **(top right corner of the screen).</li><li>Then, a pop-up will appear with information on how to <strong>Manually Create a Table</strong>, as well as the Table Title and Table Description boxes. <img src="https://ninjatables.com/wp-content/uploads/2022/09/Manually-create-a-table-1024x575.webp" alt="Popup"> You can see on the right-hand side there are 2 empty boxes- Table Title and Table Description. Fill these boxes up with a title and a description. The table description is optional, but you must name the table.</li></ul><h2 id="table-title" tabindex="-1"><strong>Table Title</strong> <a class="header-anchor" href="#table-title" aria-label="Permalink to &quot;**Table Title**&quot;">​</a></h2><p>Table Title is a <strong>required</strong> field that must be filled out. The table Title identifies your table.</p><h2 id="table-description" tabindex="-1"><strong>Table Description</strong> <a class="header-anchor" href="#table-description" aria-label="Permalink to &quot;**Table Description**&quot;">​</a></h2><p>A table description is information about the data the table is about. The HTML Field allows you to make text bold/italic, change the font color, add media files, create lists, and add anchor links. <img src="https://ninjatables.com/wp-content/uploads/2022/09/description-1024x469.webp" alt=""></p><ul><li>Lastly, click on the <strong>Add</strong> button to add a new table. The Ninja Tables dashboard will show all the tables you created and for this Demo Table, it will show the description as well. The title and description would only be visible if you allow them. Customize this setting from the &quot;<a href="https://ninjatables.com/docs/table-style-settings/" target="_blank" rel="noreferrer">Table Styling</a>&quot; tab. This is all about the <strong>Table Title <strong>and</strong> Table Description!</strong></li></ul>',8)])])}const T=e(n,[["render",o]]);export{h as __pageData,T as default};
